import{_ as p,a0 as r,w as d,s as u,ao as a,I as o,x as e,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"在 Apache、NGINX 和 Lighttpd 上啓用 HTTP 公鑰固定擴展（HPKP） | LCTT x X-CMD","titleTemplate":false,"description":"在 Apache、NGINX 和 Lighttpd 上啓用 HTTP 公鑰固定擴展（HPKP） | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Apache、NGINX 和 Lighttpd 上啓用 HTTP 公鑰固定擴展（HPKP） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Apache、NGINX 和 Lighttpd 上啓用 HTTP 公鑰固定擴展（HPKP） | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150415 HTTP Public Key Pinning Extension HPKP for Apache, NGINX and Lighttpd","title":"在 Apache、NGINX 和 Lighttpd 上啓用 HTTP 公鑰固定擴展（HPKP）","tag":"201504","desc":""},"relativePath":"201504/20150415 HTTP Public Key Pinning Extension HPKP for Apache, NGINX and Lighttpd.md","filePath":"[post].md"}'),s={name:"201504/20150415 HTTP Public Key Pinning Extension HPKP for Apache, NGINX and Lighttpd.md"};function P(T,t,m,h,C,f){const i=r("Link");return d(),u("div",null,[t[36]||(t[36]=a('<h1 id="在-apache、nginx-和-lighttpd-上啓用-http-公鑰固定擴展-hpkp" tabindex="-1">在 Apache、NGINX 和 Lighttpd 上啓用 HTTP 公鑰固定擴展（HPKP） <a class="header-anchor" href="#在-apache、nginx-和-lighttpd-上啓用-http-公鑰固定擴展-hpkp" aria-label="Permalink to “在 Apache、NGINX 和 Lighttpd 上啓用 HTTP 公鑰固定擴展（HPKP）”">​</a></h1><p>公鑰固定（Public Key Pinning）是指一個證書鏈中必須包含一個白名單中的公鑰，也就是説只有被列入白名單的證書籤發機構（CA）才能為某個域名<code>*.example.com</code>簽發證書，而不是你的瀏覽器中所存儲的任何 CA 都可以為之簽發。本文講述了這種機制的背景知識，並提供了 Apache、 Lighttpd 和 NGINX 上的配置範例。</p><h3 id="http-公鑰固定擴展" tabindex="-1">HTTP 公鑰固定擴展 <a class="header-anchor" href="#http-公鑰固定擴展" aria-label="Permalink to “HTTP 公鑰固定擴展”">​</a></h3><p>用你使用的銀行做個例子，它一直使用 CA 公司 A 為其簽發證書。但是在當前的證書體系下，CA 公司 B、CA 公司 C 和 NSA 的 CA 都能給你的銀行創建證書，而你的瀏覽器會毫無疑慮的接受它們，因為這些公司都是你所信任的根 CA。</p><p>如果你的銀行實現了 HPKP 並固定了它們的第一個中級證書（來自 CA 公司 A），那麼瀏覽器將不會接受來自CA 公司 B 和 CA 公司 C 的證書，即便它們也有一個有效的信任鏈。HPKP 也允許你的瀏覽器將這種違例行為報告給該銀行，以便銀行知道被偽造證書攻擊了。</p><p>HTTP 公鑰固定擴展是一個從2011年開始開發的針對 HTTP 用户代理（即瀏覽器）的公鑰固定標準。它由 Google 發起，甚至在 Chrome 中實現的固定機制可以使用一個人工維護的網站公鑰固定列表，這個列表包含了固定的幾個網站的公鑰簽名。（LCTT 譯註：Chrome 和 FireFox 32 及以後版本都支持公鑰固定機制，並使用內置的人工維護的公鑰固定列表數據，這些數據隨着瀏覽器軟件的更新而更新，主要包括幾個大型站點。目前還只有 Chrome 38+ 支持通過 HTTP 響應頭傳遞公鑰固定信息。）</p><p>以下是 HPKP 的幾個功能簡述：</p><ul><li>HPKP 是在 HTTP 層面設置的，使用 <code>Public-Key-Pins</code> （PKP）響應頭。</li><li>該規則的保留週期通過 max-age 參數設置，單位是秒。</li><li>PKP 響應頭只能用於正確的安全加密通訊裏面。</li><li>如果出現了多個這樣的響應頭，則只處理第一個。</li><li>固定機制可以使用<code>includeSubDomains</code>參數擴展到子域。</li><li>當接收到一個新的 PKP 響應頭時，它會覆蓋之前存儲的公鑰固定和元數據。</li><li>公鑰固定是用哈希算法生成的，其實是一個“主題公鑰信息（SKPI）”指紋。</li></ul><p>本文首先會介紹一些 HPKP 工作的原理，接下來我們會展示給你如何得到需要的指紋並配置到 web 服務器中。</p><h3 id="spki-指紋-理論" tabindex="-1">SPKI 指紋 - 理論 <a class="header-anchor" href="#spki-指紋-理論" aria-label="Permalink to “SPKI 指紋 - 理論”">​</a></h3>',10)),o("p",null,[t[1]||(t[1]=e("以下摘自 Adam Langley 的",-1)),n(i,{href:"http://www.imperialviolet.org/2011/05/04/pinning.html"},{default:l(()=>[...t[0]||(t[0]=[e("帖子",-1)])]),_:1}),t[2]||(t[2]=e("，我們哈希的是一個公鑰，而不是證書：",-1))]),t[37]||(t[37]=a('<blockquote><p>通常來説，對證書進行哈希是一個顯而易見的解決方案，但是其實這是錯的。不能這樣做的原因是 CA 證書可以不斷重新簽發：同一個公鑰、主題名可以對應多個證書，而這些證書有不同的延展或失效時間。瀏覽器從下至上地在證書池中構建證書鏈時，另外一個版本的證書可能就替代匹配了你原本所期望的證書。</p><p>舉個例子，StartSSL 有兩個根證書：一個是以 SHA1 簽名的，另外是一個是 SHA256。如果你希望固定住 StartSSL 作為你的 CA，那麼你該使用哪個證書呢？你也許可以使用這兩個，但是如果我不告訴你，你怎麼會知道還有一個根證書呢？</p><p>相反地，對公鑰進行哈希則不會有這個問題：</p><p>瀏覽器假定子證書是固定不動的：它總是證書鏈的起點。子證書所攜帶的簽名一定是一個有效的簽名，它來自其父證書給這個證書專門簽發的。這就是説，父證書的公鑰相對於子證書來説是固定的。所以可推論公鑰鏈是固定的。</p><p>唯一的問題是你不能固定到一個交叉認證的根證書上。舉個例子，GoDaddy 的根證書是 Valicert 簽名的，這是為了讓那些不能識別 GoDaddy 根證書的老客户可以信任其證書。然而，你不能固定到 Valicert 上，因為新的客户在證書鏈上發現了 GoDaddy 證書就會停止上溯（LCTT 譯註：所以就找不到固定信息了）。</p><p>此外，我們是對 SubjectPublicKeyInfo（SPKI）進行哈希而不是對公鑰位串。SPKI 包括了公鑰類型、公鑰自身及其相關參數。這很重要，因為如果對公鑰進行哈希就有可能導致發生曲解攻擊。對於一個 Diffie-Hellman 公鑰而言：如果僅對公鑰進行哈希，而不是對完整的 SPKI，那麼攻擊者可以使用同樣的公鑰而讓客户端將其解釋為其它組。同樣地，這樣也有可能強制將一個 RSA 密鑰當成 DSA 密鑰解釋等等。</p></blockquote><h3 id="固定在哪裏" tabindex="-1">固定在哪裏 <a class="header-anchor" href="#固定在哪裏" aria-label="Permalink to “固定在哪裏”">​</a></h3><p>你應該固定在什麼地方？固定你自己的公鑰並不是一個最好的辦法。你的密鑰也許會改變或撤銷。你也許會使用多個證書，經常輪換證書的話密鑰就改變了。也許由於服務器被入侵而撤銷證書。</p><p>最容易但是不是太安全的方法是固定第一個中級 CA 證書。該證書是簽名在你的網站證書之上的，所以簽發該證書的 CA 的公鑰肯定是在證書鏈上的。</p><p>採用這種方法你可以從同一個 CA 更新你的證書而不用擔心固定信息不對。如果該 CA 發行了一個不同的根證書，也許你會遇到一些問題，對此並沒有太好的解決方案。不過你可以通過如下做法來減輕這種問題的影響：</p><ul><li>從一個不同的 CA 申請一個備用的證書，並固定該備份。</li></ul><p>RFC 裏面説你至少需要做兩個固定。一個是當前連接所使用的證書鏈上的，另外一個是備份的。</p><p>另外的固定是對備份公鑰的，它可以是來自另外一個給你簽發證書的不同 CA 的 SKPI 指紋。</p>',8)),o("p",null,[t[4]||(t[4]=e("在這個問題上還有一種",-1)),t[5]||(t[5]=o("strong",null,"更安全",-1)),t[6]||(t[6]=e("的方法，就是事先創建好至少三個獨立的公鑰（使用 OpenSSL，參見",-1)),n(i,{href:"https://raymii.org/s/software/OpenSSL_Command_Generator.html"},{default:l(()=>[...t[3]||(t[3]=[e("此頁",-1)])]),_:1}),t[7]||(t[7]=e(" 瞭解 Javascript OpenSSL 命令生成器），並將其中兩個備份到一個安全的地方，離線存儲、不要放到網上。",-1))]),t[38]||(t[38]=o("p",null,"為這三個證書創建 SPKI 指紋並固定它們，然後僅使用第一個作為當前的證書。當需要時，你可以使用備份密鑰之一。不過你需要讓 CA 給你做簽名來生成證書對，這可能需要幾天，依你的 CA 的工作情況而定。",-1)),t[39]||(t[39]=o("p",null,"對於 HPKP 來説這沒有問題，因為我們使用的是公鑰的 SPKI 哈希，而不是證書。失效或不同的 CA 簽名鏈並不影響。",-1)),t[40]||(t[40]=o("p",null,"如果你按照上述方法生成並安全存儲了至少三個獨立的密鑰，並固定它們，也可以防止你的 CA 撤銷你的網站證書並簽發一個假證書時出現問題。",-1)),t[41]||(t[41]=o("h3",{id:"spki-指紋",tabindex:"-1"},[e("SPKI 指紋 "),o("a",{class:"header-anchor",href:"#spki-指紋","aria-label":"Permalink to “SPKI 指紋”"},"​")],-1)),o("p",null,[t[9]||(t[9]=e("可以使用如下的 OpenSSL 命令來生成 SPKI 指紋，它出現在 ",-1)),n(i,{href:"https://tools.ietf.org/html/draft-ietf-websec-key-pinning-21#appendix-A"},{default:l(()=>[...t[8]||(t[8]=[e("RFC 草案",-1)])]),_:1}),t[10]||(t[10]=e(" 中：",-1))]),t[42]||(t[42]=o("pre",null,[o("code",null,`openssl x509 -noout -in certificate.pem -pubkey | \\
openssl asn1parse -noout -inform pem -out public.key;
openssl dgst -sha256 -binary public.key | openssl enc -base64
`)],-1)),t[43]||(t[43]=o("p",null,"結果：",-1)),t[44]||(t[44]=o("pre",null,[o("code",null,`klO23nT2ehFDXCfx3eHTDRESMz3asj1muO+4aIdjiuY=
`)],-1)),o("p",null,[t[12]||(t[12]=e("上面輸入的 ",-1)),t[13]||(t[13]=o("code",null,"certificate.pem",-1)),t[14]||(t[14]=e(" 文件是本站（",-1)),n(i,{href:"https://raymii.org"},{default:l(()=>[...t[11]||(t[11]=[e("https://raymii.org",-1)])]),_:1}),t[15]||(t[15]=e("）的證書鏈中第一個證書。（在寫本文時， ",-1)),t[16]||(t[16]=o("code",null,"COMODO RSA Domain Validation Secure Server CA, 序列號 2B:2E:6E:EA:D9:75:36:6C:14:8A:6E:DB:A3:7C:8C:07 。",-1)),t[17]||(t[17]=e("）。",-1))]),t[45]||(t[45]=o("p",null,"你也需要同樣對你的另外兩個備份公鑰生成指紋。",-1)),t[46]||(t[46]=o("h3",{id:"故障",tabindex:"-1"},[e("故障 "),o("a",{class:"header-anchor",href:"#故障","aria-label":"Permalink to “故障”"},"​")],-1)),o("p",null,[t[20]||(t[20]=e("在寫本文時（2015/1），唯一支持 HPKP 的瀏覽器（chrome）有一個嚴重的問題：Chrome 並不能夠區分 HSTS 和 HPKP 響應頭中的 max-age 和 includeSubdomains 參數。也就是説，如果你的 HSTS 和 HPKP 設置了不同的 max-age 和 includeSubdomains 參數，它們會互相搞亂。關於這個故障的更多信息參見：",-1)),n(i,{href:"https://code.google.com/p/chromium/issues/detail?id=444511"},{default:l(()=>[...t[18]||(t[18]=[e("https://code.google.com/p/chromium/issues/detail?id=444511",-1)])]),_:1}),t[21]||(t[21]=e("。感謝 Scott Helme（",-1)),n(i,{href:"https://scotthelme.co.uk/"},{default:l(()=>[...t[19]||(t[19]=[e("https://scotthelme.co.uk",-1)])]),_:1}),t[22]||(t[22]=e("）發現並告訴我這個 Chromium 項目的問題。",-1))]),t[47]||(t[47]=a(`<h3 id="web-服務器配置" tabindex="-1">Web 服務器配置 <a class="header-anchor" href="#web-服務器配置" aria-label="Permalink to “Web 服務器配置”">​</a></h3><p>下面你可以看到三個主流 Web 服務器的配置方法。這只是一個 HTTP 響應頭，絕大多數 Web 服務器都可以設置它。它只需要設置到 HTTPS 網站上。</p><p>下面的例子固定到 <code>COMODO RSA Domain Validation Secure Server CA</code> 及備份的 <code>Comodo PositiveSSL</code> CA 上，30天失效期，包括所有的子域。</p><h4 id="apache" tabindex="-1">Apache <a class="header-anchor" href="#apache" aria-label="Permalink to “Apache”">​</a></h4><p>編輯你的 Apache 配置文件（如 <code>/etc/apache2/sites-enabled/website.conf 或 /etc/apache2/httpd.conf</code>），並添加下列行到你的 VirtualHost 中：</p><pre><code># 如需要，載入 headers 模組。
LoadModule headers_module modules/mod_headers.so

Header set Public-Key-Pins &quot;pin-sha256=\\&quot;klO23nT2ehFDXCfx3eHTDRESMz3asj1muO+4aIdjiuY=\\&quot;; pin-sha256=\\&quot;633lt352PKRXbOwf4xSEa1M517scpD3l5f79xMD9r9Q=\\&quot;; max-age=2592000; includeSubDomains&quot;
</code></pre><h4 id="lighttpd" tabindex="-1">Lighttpd <a class="header-anchor" href="#lighttpd" aria-label="Permalink to “Lighttpd”">​</a></h4><p>Lighttpd 更簡單一些，將下列行添加到你的 Lighttpd 配置文件（如 <code>/etc/lighttpd/lighttpd.conf</code>）：</p><pre><code>server.modules += ( &quot;mod_setenv&quot; )
$HTTP[&quot;scheme&quot;] == &quot;https&quot; {
    setenv.add-response-header  = ( &quot;Public-Key-Pins&quot; =&gt; &quot;pin-sha256=\\&quot;klO23nT2ehFDXCfx3eHTDRESMz3asj1muO+4aIdjiuY=\\&quot;; pin-sha256=\\&quot;633lt352PKRXbOwf4xSEa1M517scpD3l5f79xMD9r9Q=\\&quot;; max-age=2592000; includeSubDomains&quot;)
}
</code></pre><h4 id="nginx" tabindex="-1">NGINX <a class="header-anchor" href="#nginx" aria-label="Permalink to “NGINX”">​</a></h4><p>NGINX 的配置更簡短。添加以下行到你的 HTTPS 配置的 server 塊中：</p><pre><code>add_header Public-Key-Pins &#39;pin-sha256=&quot;klO23nT2ehFDXCfx3eHTDRESMz3asj1muO+4aIdjiuY=&quot;; pin-sha256=&quot;633lt352PKRXbOwf4xSEa1M517scpD3l5f79xMD9r9Q=&quot;; max-age=2592000; includeSubDomains&#39;;
</code></pre><h3 id="報告功能" tabindex="-1">報告功能 <a class="header-anchor" href="#報告功能" aria-label="Permalink to “報告功能”">​</a></h3><p>HPKP 報告功能允許瀏覽器報告任何違例給你。</p><p>如果你在響應頭中添加了附加的 <code>report-uri=&quot;http://example.org/hpkp-report&quot;</code> 參數，並用該 URI 處理接收到的數據的話，客户端會在發現違例時發送報告給你。這個報告是以 POST 方式發送到你指定的 report-uri 上，並以類似下面的 JSON 格式：</p><pre><code>{
    &quot;date-time&quot;: &quot;2014-12-26T11:52:10Z&quot;,
    &quot;hostname&quot;: &quot;www.example.org&quot;,
    &quot;port&quot;: 443,
    &quot;effective-expiration-date&quot;: &quot;2014-12-31T12:59:59&quot;,
    &quot;include-subdomains&quot;: true,
    &quot;served-certificate-chain&quot;: [
        &quot;-----BEGINCERTIFICATE-----\\nMIIAuyg[...]tqU0CkVDNx\\n-----ENDCERTIFICATE-----&quot;
    ],
    &quot;validated-certificate-chain&quot;: [
        &quot;-----BEGINCERTIFICATE-----\\nEBDCCygAwIBA[...]PX4WecNx\\n-----ENDCERTIFICATE-----&quot;
    ],
    &quot;known-pins&quot;: [
        &quot;pin-sha256=\\&quot;dUezRu9zOECb901Md727xWltNsj0e6qzGk\\&quot;&quot;,
        &quot;pin-sha256=\\&quot;E9CqVKB9+xZ9INDbd+2eRQozqbQ2yXLYc\\&quot;&quot;
    ]
}
</code></pre><h3 id="非強制-只報告" tabindex="-1">非強制，只報告 <a class="header-anchor" href="#非強制-只報告" aria-label="Permalink to “非強制，只報告”">​</a></h3><p>HPKP 也可以設置為非強制的，可以使用 <code>Public-Key-Pins-Report-Only</code> 來只發送違例報告給你。</p><p>這樣可以讓你在網站不可訪問或 HPKP 配置不正確時不固定，之後你可以將這個響應頭改為 <code>Public-Key-Pins</code> 來強制固定。</p><hr>`,20)),o("p",null,[t[24]||(t[24]=e("via: ",-1)),n(i,{href:"https://raymii.org/s/articles/HTTP_Public_Key_Pinning_Extension_HPKP.html"},{default:l(()=>[...t[23]||(t[23]=[e("https://raymii.org/s/articles/HTTP_Public_Key_Pinning_Extension_HPKP.html",-1)])]),_:1})]),o("p",null,[t[28]||(t[28]=e("作者：",-1)),n(i,{href:"https://raymii.org/"},{default:l(()=>[...t[25]||(t[25]=[e("Remy van Elst",-1)])]),_:1}),t[29]||(t[29]=e(" 譯者：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[26]||(t[26]=[e("wxy",-1)])]),_:1}),t[30]||(t[30]=e(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[27]||(t[27]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[33]||(t[33]=e("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[31]||(t[31]=[e("LCTT",-1)])]),_:1}),t[34]||(t[34]=e(" 原創翻譯，",-1)),n(i,{href:"http://linux.cn/"},{default:l(()=>[...t[32]||(t[32]=[e("Linux中國",-1)])]),_:1}),t[35]||(t[35]=e(" 榮譽推出",-1))])])}const g=p(s,[["render",P]]);export{A as __pageData,g as default};
